draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // desk
  ctx.fillRect(W/2-50, H/2+20, 100, 10);

  // chair
  ctx.fillRect(W/2-20, H/2+40, 40, 10);
  ctx.fillRect(W/2-20, H/2+50, 10, 20);

  // person
  ctx.beginPath();
  ctx.arc(W/2, H/2-50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-30);
  ctx.lineTo(W/2, H/2-10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-20);
  ctx.lineTo(W/2-20, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-20);
  ctx.lineTo(W/2+20, H/2);
  ctx.stroke();

  // book
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2-30, H/2-80, 60, 10);

  // focus lines
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-50);
  ctx.lineTo(W/2, H/2-80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-10+20*Math.sin(t), H/2-60);
  ctx.lineTo(W/2+10+20*Math.sin(t), H/2-60);
  ctx.stroke();

  ctx.restore();
}
